        //
        //     {
        //         "jsonrpc": "2.0",
        //         "id": 1,
        //         "result": { "node_id": "73cf456f7cb78d59" }
        //     }
        //
        // the future stays resolved, so later private watches on this connection skip the auth request
        Future future = client.getFuture("authenticated");
        if ((future != null))
